{"command":"python3 - <<'PY'
import json, os, collections
p=os.path.expanduser('~/.hermes/cron/jobs.json')
with open(p) as f:
    data=json.load(f)
jobs=data['jobs'] if isinstance(data,dict) and 'jobs' in data else data
never=[j['name'] for j in jobs if not j.get('last_run_at')]
slots=collections.defaultdict(list)
for j in jobs:
    expr=j['schedule']['expr'] if isinstance(j.get('schedule'),dict) else j.get('schedule','')
    parts=expr.split()
    if len(parts)>=2:
        slots[(parts[0],parts[1])].append(j['name'])
print(json.dumps({
  'total_jobs': len(jobs),
  'never_run_count': len(never),
  'never_run_names': never,
  'collisions': {f'{m} {h}': names for (m,h),names in slots.items() if len(names)>1}
}, ensure_ascii=False, indent=2))
PY","timeout":60}
